import 'package:flutter/foundation.dart' show SynchronousFuture;
import 'package:flutter/widgets.dart';

/// Lightweight, dependency-free localization for INO.
///
/// Supported languages: English (`en`), Hindi (`hi`), and Telugu (`te`). Strings are looked up by key with an English fallback, so a missing
/// translation degrades gracefully rather than showing a blank or crashing.
///
/// Usage:
/// ```dart
/// final l10n = AppLocalizations.of(context);
/// Text(l10n.t('save'));
/// ```
///
/// The active locale is driven by [MaterialApp.locale] (see `main.dart`), which
/// in turn follows the persisted `AppSettings.language`. Changing the language
/// rebuilds every `Localizations` dependant instantly - no restart.
class AppLocalizations {
  const AppLocalizations(this.locale);

  final Locale locale;

  /// The locales the app ships translations for.
  static const List<Locale> supportedLocales = [
    Locale('en'),
    Locale('hi'),
    Locale('te'),
    
  ];

  static const LocalizationsDelegate<AppLocalizations> delegate =
      _AppLocalizationsDelegate();

  /// English fallback used when no [AppLocalizations] is in the tree (e.g. a
  /// widget test that doesn't register the delegate) - never returns null.
  static const AppLocalizations _fallback = AppLocalizations(Locale('en'));

  static AppLocalizations of(BuildContext context) =>
      Localizations.of<AppLocalizations>(context, AppLocalizations) ?? _fallback;

  /// The language code currently being displayed.
  ///
  /// Kept in sync by the app root (see `main.dart`), which already rebuilds on
  /// every change to the persisted `AppSettings.language`.
  static String activeLanguageCode = 'en';

  /// The active translations for code running **outside** the widget tree -
  /// services, background jobs and the search index, which have no
  /// [BuildContext] to read [Localizations] from.
  ///
  /// Widgets must keep using [of] so they rebuild when the language changes;
  /// this getter is a snapshot, not a subscription.
  static AppLocalizations get current =>
      AppLocalizations(Locale(activeLanguageCode));

  /// Translates [key] into the active language, falling back to English and
  /// finally to the key itself (so a typo is visible rather than blank).
  String t(String key) {
    final lang = _strings[locale.languageCode] ?? _strings['en']!;
    return lang[key] ?? _strings['en']![key] ?? key;
  }

  /// Short month names, indexed by `month - 1`.
  static const List<String> _monthKeys = [
    'monJan', 'monFeb', 'monMar', 'monApr', 'monMay', 'monJun', //
    'monJul', 'monAug', 'monSep', 'monOct', 'monNov', 'monDec',
  ];

  /// The abbreviated month name ("Jan") in the active language. [month] is 1-12.
  String monthShort(int month) => t(_monthKeys[month - 1]);

  /// The English text for [key], regardless of the active language.
  ///
  /// For the handful of places that must stay language-independent: file names,
  /// export/PDF metadata and debug logs.
  static String english(String key) => _strings['en']![key] ?? key;

  /// Every translation of [key] across the supported languages.
  ///
  /// Used by search indexes so a query matches whichever language the user is
  /// typing in, not just the one the UI happens to be showing.
  static List<String> allTranslations(String key) => [
        for (final lang in _strings.values)
          if (lang[key] != null) lang[key]!,
      ];

  // Convenience getters for the highest-traffic strings.
  String get home => t('home');
  String get wallet => t('wallet');
  String get scan => t('scan');
  String get reminders => t('reminders');
  String get profile => t('profile');

  String get save => t('save');
  String get cancel => t('cancel');
  String get create => t('create');
  String get upload => t('upload');
  String get delete => t('delete');
  String get retake => t('retake');

  String get crop => t('crop');
  String get rotate => t('rotate');
  String get enhance => t('enhance');

  String get language => t('language');
  String get notifications => t('notifications');
  String get darkMode => t('darkMode');
}

class _AppLocalizationsDelegate
    extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) =>
      const {'en', 'hi', 'te'}.contains(locale.languageCode);

  // Resolve synchronously (like Flutter's own delegates) so switching language
  // never flashes an empty frame and the widget tree builds in the same frame.
  @override
  Future<AppLocalizations> load(Locale locale) =>
      SynchronousFuture<AppLocalizations>(AppLocalizations(locale));

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}

