    'privacyControlsHeading': 'आपके नियंत्रण',
    'privacyOverviewBody': 'INO (Intelligent Network Organizer) आपके निजी दस्तावेज़ों को सुरक्षित रूप से सहेजने और व्यवस्थित करने में मदद करता है। यह नीति बताती है कि हम क्या जानकारी लेते हैं, उसका उपयोग कैसे करते हैं और आपके पास कौन-से विकल्प हैं।',
    'privacyStorageBody': 'फ़ाइलें एक निजी, नियंत्रित पहुँच वाले क्लाउड स्टोरेज में रखी जाती हैं, जहाँ केवल आपके प्रमाणित सत्र से ही पहुँचा जा सकता है। जिन दस्तावेज़ों को आपने सुरक्षित चिह्नित किया है, उन्हें खोलने से पहले डिवाइस पर बायोमेट्रिक पुष्टि ज़रूरी होती है।',
