    'consentSheetBody': 'మీ పాస్‌వర్డ్ పూర్తి భద్రతతో సేవ్ అవుతుంది - నిల్వ చేయకముందే మీ వాల్ట్ పాస్‌ఫ్రేజ్‌తో ఈ పరికరంలోనే ఎన్‌క్రిప్ట్ చేయబడుతుంది, కాబట్టి దీన్ని ఎవరూ చదవలేరు.\n\nఅంగీకరించే ముందు ఒక పరిశీలన: మీరు నిజమైన పేరు కాకుండా మారుపేరు నమోదు చేశారని నిర్ధారించుకోండి. "Instagram"ను "ramu1243" పాస్‌వర్డ్‌తో సేవ్ చేస్తే ఆ రెండూ కలిసిపోతాయి - "నీలి చిలుక" లాంటి యాదృచ్ఛిక మారుపేరు వాటిని వేరుగా ఉంచుతుంది.',
