    'onboardingBody1': 'ఆధార్, పాన్, పాస్‌పోర్ట్ ఇంకా ఎన్నో - సురక్షితంగా, ఎప్పుడూ మీ చేతిలో.',
    'onboardingBody2': 'ఆస్తి, పెట్టుబడులు, ఆరోగ్య రికార్డులు - అన్నీ ఒక్క చూపులో చక్కగా.',
