    'onboardingTitle3': 'వెంటనే, సురక్షితంగా\nపంచుకోండి',
    'oneDocumentExpiringSoon': '1 పత్రం త్వరలో గడువు ముగుస్తోంది',
    'openDeviceSettings': 'పరికర సెట్టింగ్‌లను తెరవండి',
    'privacyBiometricsBody': 'బయోమెట్రిక్ తనిఖీలు పూర్తిగా మీ పరికరంలో ఆపరేటింగ్ సిస్టమ్ ద్వారానే జరుగుతాయి. INO మీ వేలిముద్ర లేదా ముఖ డేటాను ఎప్పుడూ స్వీకరించదు, భద్రపరచదు, పంపదు - కేవలం సురక్షితమైన ఆన్/ఆఫ్ ప్రాధాన్యతను మాత్రమే ఉంచుతుంది.',
    'privacyBiometricsHeading': 'బయోమెట్రిక్స్',
    'privacyCollectBody': 'మీరు ఇచ్చే ఖాతా వివరాలు (పేరు, ఇమెయిల్, ఫోన్), మీరు జోడించే పత్రాలు, వాటి వివరాలు, అలాగే యాప్ ప్రాథమిక ప్రాధాన్యతలు. మేము మీ వ్యక్తిగత డేటాను విక్రయించము.',
    'privacyCollectHeading': 'మేము సేకరించే సమాచారం',
    'privacyContactBody': 'గోప్యత గురించి ప్రశ్నలా? ప్రొఫైల్ → సపోర్ట్‌ను సంప్రదించండి ద్వారా మమ్మల్ని చేరుకోండి.',
    'privacyContactHeading': 'సంప్రదింపు',
    'privacyControlsBody': 'మీరు ఎప్పుడైనా మీ ఫైళ్లు మరియు బ్యాకప్‌లను ఎగుమతి చేయవచ్చు, మీ ఖాతాను శాశ్వతంగా తొలగించవచ్చు - దీనితో మీ పత్రాలు, ఫైళ్లు, ప్రొఫైల్ తొలగిపోతాయి.',
    'privacyControlsHeading': 'మీ నియంత్రణలు',
    'privacyOverviewBody': 'INO (Intelligent Network Organizer) మీ వ్యక్తిగత పత్రాలను సురక్షితంగా భద్రపరచడానికి, చక్కగా అమర్చడానికి సహాయపడుతుంది. మేము ఏ సమాచారం సేకరిస్తాము, దానిని ఎలా ఉపయోగిస్తాము, మీకు ఏ ఎంపికలు ఉన్నాయో ఈ విధానం వివరిస్తుంది.',
    'privacyStorageBody': 'ఫైళ్లు ప్రైవేట్, నియంత్రిత యాక్సెస్ ఉన్న క్లౌడ్ నిల్వలో ఉంచబడతాయి; వాటిని మీ ధృవీకరించిన సెషన్‌తో మాత్రమే చేరుకోగలరు. మీరు రక్షితంగా గుర్తు పెట్టిన పత్రాలను తెరవడానికి ముందు పరికరంలో బయోమెట్రిక్ ధృవీకరణ అవసరం.',
